def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    budget = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    supply = day_context['supply']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return min(budget, 20)
        return min(budget, 8)

    prev_bids = []
    desperate_opp = False
    rich_opp = False
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_opp = True
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp = True
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    expected_units = int(supply / WATER_REQ)
    player_count = 1 + len(alive_opponents)
    scarcity = expected_units < player_count

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    if hp <= 1:
        target = DAILY_SALARY * 0.98
    elif hp <= 2 or no_water >= 2:
        target = max(DAILY_SALARY * 0.88, highest_prev + 2)
    elif no_water >= 1:
        target = max(DAILY_SALARY * 0.72, avg_prev + 2)
    else:
        if scarcity:
            if highest_prev >= DAILY_SALARY * 0.85:
                target = DAILY_SALARY * 0.52
            elif highest_prev > 0:
                target = max(DAILY_SALARY * 0.58, highest_prev + 1.5)
            else:
                target = DAILY_SALARY * 0.56
        else:
            if highest_prev >= DAILY_SALARY * 0.8:
                target = DAILY_SALARY * 0.34
            elif highest_prev > 0:
                target = max(DAILY_SALARY * 0.4, avg_prev * 0.82)
            else:
                target = DAILY_SALARY * 0.38

    if desperate_opp and hp > 2 and no_water == 0:
        target *= 0.9
    if rich_opp and scarcity and hp <= 3:
        target = max(target, highest_prev + 2)

    reserve_days = 2 if hp > 2 else 1
    max_affordable_today = max(0, budget - reserve_days * DAILY_SALARY * 0.35)
    if hp <= 2 or no_water >= 1:
        max_affordable_today = budget

    bid = min(target, max_affordable_today, budget)
    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids (immediate reaction only)
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    max_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If someone bid very high yesterday, they likely try to lock water again.
    # We respond with a moderate-to-high bid depending on our hp and budget.
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])

    # Estimate how many units water we can realistically aim for.
    # In this game, bid is in currency; we use supply to decide urgency.
    # If supply is low, we need more water to avoid no-water days.
    scarcity = (supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0)

    # Base target bid
    if max_prev_bid >= DAILY_SALARY * 0.85:
        # Opponent likely in high-pressure mode
        if hp <= 2.0 or scarcity:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * 0.65
    elif max_prev_bid >= DAILY_SALARY * 0.55:
        if hp <= 2.0:
            target = DAILY_SALARY * 0.85
        else:
            target = DAILY_SALARY * 0.55
    else:
        # No strong signal; bid to secure without overspending
        if hp <= 2.0 or scarcity:
            target = DAILY_SALARY * 0.6
        else:
            target = DAILY_SALARY * 0.45

    # If our budget is tight, scale down.
    # Also avoid bidding above budget.
    bid = min(budget, target)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    # Small day-based jitter to break ties deterministically
    # (bounded and budget-safe)
    jitter = (day % 3) * 2.0
    bid = min(budget, bid + jitter)

    return float(bid)
